from __future__ import annotations

import base64
import io
import tarfile
from pathlib import Path

PAYLOAD = """[... ELLIPSIZATION ...]"""
DELETE_PATHS = (
    "discord_bot/cogs/campus_attendance.py",
    "discord_bot/cogs/campus_study.py",
)


def main() -> None:
    root = Path(__file__).resolve().parents[1]
    data = base64.b64decode(PAYLOAD)
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
        for member in archive.getmembers():
            target = (root / member.name).resolve()
            if root not in target.parents and target != root:
                raise RuntimeError(f"unsafe archive path: {member.name}")
        archive.extractall(root)

    for relative in DELETE_PATHS:
        path = root / relative
        if path.exists():
            path.unlink()

    # This one-shot helper and its workflow remove themselves after applying the patch.
    workflow = root / ".github/workflows/apply-simplify.yml"
    if workflow.exists():
        workflow.unlink()
    Path(__file__).unlink()


if __name__ == "__main__":
    main()
